def deep_copy_object_with_type_hints(obj: typing.Any) -> typing.Any:
    if isinstance(obj, typing.List):
        return typing.List[typing.Any]([deep_copy_object_with_type_hints(i) for i in obj])
    elif isinstance(obj, typing.Dict):
        return typing.Dict[str, typing.Any]({(k, deep_copy_object_with_type_hints(v)): v for k, v in obj.items()})
