    elif isinstance(obj, typing.TypeVar):
        return obj
    elif isinstance(obj, typing.Generic):
        return typing.Generic(tuple(map(deep_copy_object_with_type_hints, obj.__args__)))
    else:
        return copy.deepcopy(obj)

